from flask_wtf import FlaskForm
from flask_wtf.file import FileField
from wtforms import StringField, TextAreaField, SelectField, DateField, TimeField, SubmitField
from wtforms.validators import DataRequired, Length, Optional
class ItemForm(FlaskForm):
    category_id=SelectField('Category',coerce=int,validators=[DataRequired()]); title=StringField('Item title',validators=[DataRequired(),Length(max=140)]); description=TextAreaField('Description',validators=[DataRequired(),Length(min=5,max=3000)]); color=StringField('Color',validators=[Optional(),Length(max=60)]); brand=StringField('Brand',validators=[Optional(),Length(max=80)]); model=StringField('Model',validators=[Optional(),Length(max=80)]); location_id=SelectField('Location',coerce=int,validators=[DataRequired()]); date_event=DateField('Date',validators=[DataRequired()]); time_event=TimeField('Approximate time',validators=[Optional()]); image=FileField('Photo (optional)'); distinguishing_features=TextAreaField('Distinguishing features',validators=[Optional(),Length(max=2000)]); value_level=SelectField('Value classification',choices=[('NORMAL','Normal'),('HIGH','High value / sensitive')]); private_details=TextAreaField('Private verification details',validators=[DataRequired(),Length(min=5,max=3000)]); storage_location=StringField('Current storage location',validators=[Optional(),Length(max=160)]); submit=SubmitField('Submit report')
